package com.example.campsitelottery

import org.junit.Assert.assertEquals
import org.junit.Assert.assertNull
import org.junit.Assert.assertTrue
import org.junit.Test

/**
 * Code and documentation generated by Claude (Anthropic, Claude Opus 5.5). Estimated AI-generated share of this file: ~100%
 * Unit tests for [AdminImageList] and [InMemoryAdminImageRepository].
 */
class AdminImagesTest {

    private val lakeside = Campsite(campsiteId = "site1", ownerId = "owner1", name = "Lakeside Pines", imageUrl = "lakeImage")
    private val noImage = Campsite(campsiteId = "site2", ownerId = "owner1", name = "Bare Site", imageUrl = null)
    private val blankImage = Campsite(campsiteId = "site3", ownerId = "owner1", name = "Blank Site", imageUrl = " ")
    private val alice = ProfileImageEntry("alice", "Alice Moreau", "alicePic")
    private val zed = ProfileImageEntry("zed", "Zed Albers", "zedPic")

    private fun build(
        campsites: List<Campsite> = listOf(lakeside),
        profiles: List<ProfileImageEntry> = listOf(alice),
        owners: Map<String, String> = mapOf("owner1" to "Olive Owner"),
    ) = AdminImageList.build(campsites, owners, profiles)

    @Test
    fun buildListsCampsiteImagesThenProfilePictures() {
        val items = build()
        assertEquals(listOf("CAMPSITE_site1", "PROFILE_alice"), items.map { it.key })
        assertEquals(AdminImageItem(AdminImageKind.PROFILE, "alice", "Alice Moreau", "alice", "Alice Moreau", "alicePic"), items[1])
    }

    @Test
    fun buildSkipsCampsitesAndProfilesWithoutImages() {
        val items = build(
            campsites = listOf(lakeside, noImage, blankImage),
            profiles = listOf(alice, ProfileImageEntry("bob", "Bob", " "), ProfileImageEntry("", "Nobody", "pic")),
        )
        assertEquals(listOf("site1", "alice"), items.map { it.id })
    }

    @Test
    fun buildUsesOwnerNameWhenKnownElseIdElseUnknown() {
        val items = build(
            campsites = listOf(lakeside, lakeside.copy(campsiteId = "s2", ownerId = "owner2"), lakeside.copy(campsiteId = "s3", ownerId = "")),
            profiles = emptyList(),
        )
        assertEquals(listOf("Olive Owner", "owner2", AdminImageList.UNKNOWN_OWNER), items.map { it.ownerLabel })
    }

    @Test
    fun buildNamesUnnamedCampsitesAndUsers() {
        val items = build(campsites = listOf(lakeside.copy(name = "")), profiles = listOf(alice.copy(name = "  ")))
        assertEquals(listOf(AdminImageList.UNNAMED_CAMPSITE, AdminImageList.UNNAMED_USER), items.map { it.name })
    }

    @Test
    fun campsiteAndUserWithSameIdHaveDifferentKeys() {
        val items = build(campsites = listOf(lakeside.copy(campsiteId = "same")), profiles = listOf(alice.copy(userId = "same")))
        assertEquals(2, items.map { it.key }.toSet().size)
    }

    @Test
    fun searchMatchesUserNameAndIdIgnoringCase() {
        val items = build(profiles = listOf(alice, zed))
        assertEquals(listOf("alice"), AdminImageList.visible(items, "  MOREAU ", ImageFilterMode.ALL).map { it.id })
        assertEquals(listOf("zed"), AdminImageList.visible(items, "zed", ImageFilterMode.ALL).map { it.id })
        assertEquals(listOf("site1"), AdminImageList.visible(items, "olive", ImageFilterMode.ALL).map { it.id })
    }

    @Test
    fun searchIgnoresStoredImageDataButMatchesCampsiteWebAddress() {
        val items = build(
            campsites = listOf(lakeside.copy(imageUrl = "/9j/4AAQSkZJRgABAQ"), lakeside.copy(campsiteId = "web", name = "Web", imageUrl = "https://example.com/pines.jpg")),
            profiles = listOf(alice.copy(image = "/9j/4AAQSkZJRgABAQ")),
        )
        assertEquals(emptyList<String>(), AdminImageList.visible(items, "4aaq", ImageFilterMode.ALL).map { it.id })
        assertEquals(listOf("web"), AdminImageList.visible(items, "pines.jpg", ImageFilterMode.ALL).map { it.id })
    }

    @Test
    fun searchAndFilterCombine() {
        val items = build(campsites = listOf(lakeside.copy(name = "Alice Lake")), profiles = listOf(alice))
        assertEquals(listOf("alice"), AdminImageList.visible(items, "alice", ImageFilterMode.PROFILES).map { it.id })
        assertEquals(listOf("site1"), AdminImageList.visible(items, "alice", ImageFilterMode.CAMPSITES).map { it.id })
    }

    @Test
    fun filterShowsOnlyOneKind() {
        val items = build(profiles = listOf(alice, zed))
        assertEquals(listOf("site1"), AdminImageList.visible(items, "", ImageFilterMode.CAMPSITES).map { it.id })
        assertEquals(listOf("alice", "zed"), AdminImageList.visible(items, "", ImageFilterMode.PROFILES).map { it.id })
    }

    @Test
    fun sortByCampsitePutsCampsitesFirstThenProfilesByName() {
        val items = build(
            campsites = listOf(lakeside, lakeside.copy(campsiteId = "a", name = "Aspen Grove")),
            profiles = listOf(zed, alice),
        )
        assertEquals(
            listOf("a", "site1", "alice", "zed"),
            AdminImageList.visible(items, "", ImageFilterMode.SORT_CAMPSITE).map { it.id },
        )
    }

    @Test
    fun sortByOwnerTreatsUsersAsOwnersOfTheirPictures() {
        val items = build(profiles = listOf(zed, alice))
        assertEquals(
            listOf("Alice Moreau", "Olive Owner", "Zed Albers"),
            AdminImageList.visible(items, "", ImageFilterMode.SORT_OWNER).map { it.ownerLabel },
        )
    }

    @Test
    fun removingProfilePictureNotifiesListeners() {
        val repo = InMemoryAdminImageRepository(profiles = listOf(alice, zed))
        var seen: List<ProfileImageEntry> = emptyList()
        repo.listenToProfileImages({ seen = it }, { throw it })
        var done = false
        repo.removeProfileImage("alice", "alicePic", { done = true }, { throw it })
        assertTrue(done)
        assertEquals(listOf("zed"), seen.map { it.userId })
    }

    @Test
    fun removingChangedProfilePictureFailsAndKeepsIt() {
        val repo = InMemoryAdminImageRepository(profiles = listOf(alice))
        repo.putProfile(alice.copy(image = "newPic"))
        var error: Exception? = null
        repo.removeProfileImage("alice", "alicePic", { error("should fail") }, { error = it })
        assertEquals(AdminImageMessages.PICTURE_CHANGED, error?.message)
        assertEquals("newPic", repo.storedProfiles().single().image)
    }

    @Test
    fun removingAlreadyRemovedProfilePictureFails() {
        val repo = InMemoryAdminImageRepository()
        var error: Exception? = null
        repo.removeProfileImage("alice", "alicePic", { error("should fail") }, { error = it })
        assertEquals(AdminImageMessages.PICTURE_GONE, error?.message)
    }

    @Test
    fun removingCampsiteImageClearsOnlyThatImage() {
        val repo = InMemoryAdminImageRepository(campsites = listOf(lakeside, lakeside.copy(campsiteId = "other")))
        repo.removeCampsiteImage("site1", {}, { throw it })
        assertNull(repo.storedCampsites().single { it.campsiteId == "site1" }.imageUrl)
        assertEquals("lakeImage", repo.storedCampsites().single { it.campsiteId == "other" }.imageUrl)
    }

    @Test
    fun stoppedListenerIsNotNotified() {
        val repo = InMemoryAdminImageRepository(profiles = listOf(alice))
        var calls = 0
        val stop = repo.listenToProfileImages({ calls++ }, { throw it })
        stop()
        repo.putProfile(zed)
        assertEquals(1, calls)
    }
}
